// P41 port pilot (portsim/sim/gfx_uivec.h; log/roadmap/P41/PORT_PILOT_BRIEF.md, log/roadmap/P41/pilot/notes.md): the uivec scene
// renderer and its test entries (module gfx_uivec). The scenes are uivec_title.inc, generated by re/tools/uivec/port_export.py from
// the approved title menu scenes; every formula below is re/tools/uivec/sdf.py's, in doubles, so a render equals sdf.render of the
// same scene (port/test/test_p41_uivec.py: every scene at 1x and 2.7x).
//
// Negative controls (g_negctl_uivec, sg_negctl_set "uivec.render"):
//   1 the frame point of a target pixel half a pixel off (x / s instead of (x + 0.5) / s): every render moves (parity RED)
//   2 the bevel paint's normal turned upside down (ny negated): the lit side of every bubble, pad and disc moves to the bottom
#include "portsim/sim/gfx_uivec.h"

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <mutex>
#include <thread>
#include <unordered_map>

#include "gfx_body.h"
#include "portsim/arith.h"
#include "portsim/ptr.h"
#include "portsim/registry.h"
#include "portsim/sim/gfx.h"
#include "portsim/sim/gfx_ui.h"
#include "gfx_uivec_eval.h"

namespace portsim {

int g_negctl_uivec = 0;

namespace {

using namespace uveval;
struct UvSceneDef {
  const char *name;
  int32_t button, hover, slot, cut_x, cut_y;
  int32_t item_a, nitems;
};

#include "uivec_title.inc"

const UvSceneDef *const kUvScenes = uvt::kScenes;
const UvTab &kT = uvt::kTab;
constexpr int32_t kNumScenes = static_cast<int32_t>(sizeof(uvt::kScenes) / sizeof(uvt::kScenes[0]));

// the target rows [ra, rb) of uv_render
void render_rows(int32_t k, int32_t dx, int32_t dy, double sx, double sy, double ox, double oy, int32_t px0, int32_t py0, int32_t w,
                 int32_t h, int32_t ra, int32_t rb, std::vector<float> &prem) {
  (void)h;
  const UvSceneDef &sc = kUvScenes[k];
  const double half = SG_NEGCTL(g_negctl_uivec) == 1 ? 0.0 : 0.5;
  const double s = std::sqrt(sx * sy);   // frame units -> target pixels (the coverage's edge; sdf.render's s)
  for (int32_t it = 0; it < sc.nitems; ++it) {
    const UvItem &I = kT.items[sc.item_a + it];
    const int32_t i0 = std::max(px0, static_cast<int32_t>(std::floor((I.box[0] + dx) * sx + ox)));
    const int32_t i1 = std::min(px0 + w, static_cast<int32_t>(std::ceil((I.box[2] + dx) * sx + ox)));
    const int32_t j0 = std::max(ra, static_cast<int32_t>(std::floor((I.box[1] + dy) * sy + oy)));
    const int32_t j1 = std::min(rb, static_cast<int32_t>(std::ceil((I.box[3] + dy) * sy + oy)));
    for (int32_t ty = j0; ty < j1; ++ty) {
      const double y = (ty + half - oy) / sy - dy;
      for (int32_t tx = i0; tx < i1; ++tx) {
        const double x = (tx + half - ox) / sx - dx;
        float *dst = prem.data() + (static_cast<size_t>(ty - py0) * static_cast<size_t>(w) + static_cast<size_t>(tx - px0)) * 4u;
        double px4[4] = {dst[0], dst[1], dst[2], dst[3]};
        composite_item(kT, I, x, y, s, px4, SG_NEGCTL(g_negctl_uivec) == 2);
        const double pr = px4[0], pg = px4[1], pb = px4[2], pa = px4[3];
        dst[0] = static_cast<float>(pr);
        dst[1] = static_cast<float>(pg);
        dst[2] = static_cast<float>(pb);
        dst[3] = static_cast<float>(pa);
      }
    }
  }
}

}  // namespace

int32_t uv_scene_count() { return kNumScenes; }
const char *uv_scene_name(int32_t k) { return k >= 0 && k < kNumScenes ? kUvScenes[k].name : ""; }
int32_t uv_scene_button(int32_t k) { return k >= 0 && k < kNumScenes ? kUvScenes[k].button : -1; }
int32_t uv_scene_hover(int32_t k) { return k >= 0 && k < kNumScenes ? kUvScenes[k].hover : -1; }
int32_t uv_title_scene(int32_t button, int32_t hover) {
  for (int32_t k = 0; k < kNumScenes; ++k)
    if (kUvScenes[k].button == button && kUvScenes[k].hover == (hover ? 1 : 0)) return k;
  return -1;
}

int32_t uv_title_slot_scene(int32_t slot, int32_t &cut_x, int32_t &cut_y) {
  for (int32_t k = 0; k < kNumScenes; ++k)
    if (kUvScenes[k].slot == slot) {
      cut_x = kUvScenes[k].cut_x;
      cut_y = kUvScenes[k].cut_y;
      return k;
    }
  return -1;
}

std::string uv_run_text(int32_t k, int32_t dx, int32_t dy) {
  char b[64];
  std::snprintf(b, sizeof b, "uv:%d %d %d", static_cast<int>(k), static_cast<int>(dx), static_cast<int>(dy));
  return b;
}
bool uv_parse(const std::string &text, int32_t &k, int32_t &dx, int32_t &dy) {
  if (!uv_is_run_text(text)) return false;
  // three decimal integers separated by single spaces, nothing after them
  long v[3] = {0, 0, 0};
  const char *p = text.c_str() + 3;
  for (int i = 0; i < 3; ++i) {
    if (i > 0 && *p++ != ' ') return false;
    char *e = nullptr;
    v[i] = std::strtol(p, &e, 10);
    if (e == p) return false;
    p = e;
  }
  if (*p != '\0' || v[0] < 0 || v[0] >= kNumScenes || v[1] < -100000 || v[1] > 100000 || v[2] < -100000 || v[2] > 100000) return false;
  k = static_cast<int32_t>(v[0]);
  dx = static_cast<int32_t>(v[1]);
  dy = static_cast<int32_t>(v[2]);
  return true;
}

void uv_bounds(int32_t k, int32_t dx, int32_t dy, float &x0, float &y0, float &x1, float &y1) {
  double a = 1e9, b = 1e9, c = -1e9, d = -1e9;
  if (k >= 0 && k < kNumScenes) {
    const UvSceneDef &sc = kUvScenes[k];
    for (int32_t i = 0; i < sc.nitems; ++i) {
      const UvItem &I = kT.items[sc.item_a + i];
      a = std::min(a, I.box[0] + dx);
      b = std::min(b, I.box[1] + dy);
      c = std::max(c, I.box[2] + dx);
      d = std::max(d, I.box[3] + dy);
    }
  }
  x0 = static_cast<float>(std::max(a, 0.0));
  y0 = static_cast<float>(std::max(b, 0.0));
  x1 = static_cast<float>(std::min(c, 800.0));
  y1 = static_cast<float>(std::min(d, 600.0));
}

void uv_render(int32_t k, int32_t dx, int32_t dy, double sx, double sy, double ox, double oy, int32_t px0, int32_t py0, int32_t w,
               int32_t h, std::vector<float> &prem) {
  prem.assign(static_cast<size_t>(std::max(0, w)) * static_cast<size_t>(std::max(0, h)) * 4u, 0.f);
  if (k < 0 || k >= kNumScenes || w <= 0 || h <= 0 || sx <= 0 || sy <= 0) return;
  // bands of rows on the machine's threads (each writes only its rows), as gfx_ui.cpp ui_render; a small target on the caller's
  const int64_t px = static_cast<int64_t>(w) * h;
  const int32_t n = px < 40000 ? 1 : static_cast<int32_t>(std::min<unsigned>(std::max(1u, std::thread::hardware_concurrency()), 16u));
  const int32_t band = (h + n - 1) / n;
  std::vector<std::thread> ts;
  for (int32_t t = 1; t < n; ++t) {
    const int32_t ra = py0 + t * band, rb = std::min(py0 + h, ra + band);
    if (ra < rb) ts.emplace_back(render_rows, k, dx, dy, sx, sy, ox, oy, px0, py0, w, h, ra, rb, std::ref(prem));
  }
  render_rows(k, dx, dy, sx, sy, ox, oy, px0, py0, w, h, py0, std::min(py0 + h, py0 + band), prem);
  for (std::thread &t : ts) t.join();
}

std::shared_ptr<const UvFrame> uv_frame(const std::string &text) {
  int32_t k = 0, dx = 0, dy = 0;
  if (!uv_parse(text, k, dx, dy)) return nullptr;
  static std::mutex mu;
  static std::unordered_map<std::string, std::shared_ptr<const UvFrame>> cache;
  const int32_t mode = SG_NEGCTL(g_negctl_uivec);
  const std::string key = text + "#" + std::to_string(mode);
  {
    std::lock_guard<std::mutex> l(mu);
    auto it = cache.find(key);
    if (it != cache.end()) return it->second;
  }
  float fx0, fy0, fx1, fy1;
  uv_bounds(k, dx, dy, fx0, fy0, fx1, fy1);
  auto f = std::make_shared<UvFrame>();
  f->x0 = static_cast<int32_t>(std::floor(fx0));
  f->y0 = static_cast<int32_t>(std::floor(fy0));
  f->x1 = std::max(f->x0, static_cast<int32_t>(std::ceil(fx1)));
  f->y1 = std::max(f->y0, static_cast<int32_t>(std::ceil(fy1)));
  uv_render(k, dx, dy, 1.0, 1.0, 0.0, 0.0, f->x0, f->y0, f->x1 - f->x0, f->y1 - f->y0, f->prem);
  std::lock_guard<std::mutex> l(mu);
  if (cache.size() > 256) cache.clear();   // a bound (12 scenes; a moved draw makes another key)
  cache[key] = f;
  return f;
}

// ------------------------------------------------------------------------------------------------ test entries
namespace {
// uivec.count(): the number of scenes; uivec.scene(k): button | hover << 8 | slot << 16 of scene k (-1 for none)
void a_count(Ctx &, const uint32_t *, Ret &r) { r.set_i32(kNumScenes); }
void a_scene(Ctx &, const uint32_t *a, Ret &r) {
  const int32_t k = i32(a[0]);
  if (k < 0 || k >= kNumScenes) {
    r.set_i32(-1);
    return;
  }
  const UvSceneDef &s = kUvScenes[k];
  r.set_i32(s.button | s.hover << 8 | s.slot << 16);
}
// uivec.render(k, dx, dy, scale_x1000, va, cap): scene k moved by (dx, dy) over its bounds at scale / 1000, with the target's pixel
// (0, 0) at the frame point (X0, Y0) = the bounds' floor (target pixel (i, j) centre = (X0, Y0) + (i + 0.5, j + 0.5) / scale, as
// sdf.render with origin (X0, Y0)). va gets w, h, X0, Y0 (int32) then 4 float32 per pixel (gfx_uivec.h uv_render's prem). Returns the
// words written, 0 when cap (in words) is too small.
void a_render(Ctx &c, const uint32_t *a, Ret &r) {
  r.set_u32(0);
  const int32_t k = i32(a[0]), dx = i32(a[1]), dy = i32(a[2]);
  const double s = a[3] / 1000.0;
  if (k < 0 || k >= kNumScenes || s <= 0) return;
  float fx0, fy0, fx1, fy1;
  uv_bounds(k, dx, dy, fx0, fy0, fx1, fy1);
  const int32_t X0 = static_cast<int32_t>(std::floor(fx0)), Y0 = static_cast<int32_t>(std::floor(fy0));
  const int32_t w = static_cast<int32_t>(std::ceil((fx1 - X0) * s)), h = static_cast<int32_t>(std::ceil((fy1 - Y0) * s));
  if (w <= 0 || h <= 0 || 4u + 4ull * static_cast<uint64_t>(w) * static_cast<uint64_t>(h) > a[5]) return;
  std::vector<float> prem;
  uv_render(k, dx, dy, s, s, -X0 * s, -Y0 * s, 0, 0, w, h, prem);
  const int32_t hd[4] = {w, h, X0, Y0};
  for (int i = 0; i < 4; ++i) c.mem.store<uint32_t>(a[4] + 4u * static_cast<uint32_t>(i), u32(hd[i]));
  uint8_t *dst = c.mem.at(a[4] + 16u, static_cast<uint32_t>(prem.size() * 4u), true);
  std::memcpy(dst, prem.data(), prem.size() * 4u);
  r.set_u32(static_cast<uint32_t>(4u + prem.size()));
}
// uivec.drawTitle(slot, x, y): the title menu's Image_draw of the title button cut `slot` (showTitleScreen's SpriteRefs) at (x, y)
// on the root surface, through gfx_drop as the menu makes it; returns 1 when a body drew it
void a_draw_title(Ctx &c, const uint32_t *a, Ret &r) {
  Gfx *g = gfx(c);
  if (g == nullptr) throw MissingResource{"gfx backend (gfx.attach)"};
  const uint32_t args[5] = {state_va(c, &GameState::g_spriteRef_53b7e0) + 0x2cu * a[0], g->root_va(c), a[1], a[2], 0};
  r.set_i32(gfx_drop(c, "Image_draw", args, 5) ? 1 : 0);
}
// uivec.time(k, scale_x1000, reps): the mean wall time of uv_render of scene k over its bounds at scale / 1000, microseconds
void a_time(Ctx &, const uint32_t *a, Ret &r) {
  const int32_t k = i32(a[0]);
  const double s = a[1] / 1000.0;
  const uint32_t reps = std::max(1u, a[2]);
  float fx0, fy0, fx1, fy1;
  uv_bounds(k, 0, 0, fx0, fy0, fx1, fy1);
  const int32_t w = static_cast<int32_t>(std::ceil((fx1 - fx0) * s)), h = static_cast<int32_t>(std::ceil((fy1 - fy0) * s));
  std::vector<float> prem;
  const auto t0 = std::chrono::steady_clock::now();
  for (uint32_t i = 0; i < reps; ++i) uv_render(k, 0, 0, s, s, -fx0 * s, -fy0 * s, 0, 0, w, h, prem);
  const auto us = std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - t0).count();
  r.set_u32(static_cast<uint32_t>(us / reps));
}

const FuncDef kFuncs[] = {
    {"uivec.render", "default", "int", 6, 0, a_render, &g_negctl_uivec},
    {"uivec.count", "default", "int", 0, 0, a_count, &g_negctl_uivec},
    {"uivec.scene", "default", "int", 1, 0, a_scene, &g_negctl_uivec},
    {"uivec.drawTitle", "default", "int", 3, 0, a_draw_title, &g_negctl_uivec},
    {"uivec.time", "default", "int", 3, 0, a_time, &g_negctl_uivec},
};
}  // namespace

extern const ModuleDef kModule_gfx_uivec = {"gfx_uivec", kFuncs, sizeof(kFuncs) / sizeof(kFuncs[0])};

}  // namespace portsim
